"""Clinical mode REP functions. These functions are called from the top level IntegrityService
interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.pages.clinical_screen as ClinicalPgObj


def _clinical_launch_rep() -> bool:
    '''
    Selects the Receive External Prescription button in clinical mode
    to launch REP mode

    Returns:
        bool - True if REP mode has launched successfully
    '''
    menu = ClinicalPgObj.ClinicalMenuBar()
    if menu.ready():
        menu.rep_prescription()
        rep = ClinicalPgObj.ReceiveExternalPrescription()
        return rep.ready()
    return False